INSERT INTO course_chapters (id,course_id,parent_id,title,content,order_index,duration,is_published,created_at) VALUES
(7003001,4007,NULL,'第1章 网络概述与体系结构','网络的功能、拓扑、分层模型与性能指标。',1,320,1,'2026-09-07 08:00:00'),
(7003002,4007,NULL,'第2章 物理层','传输介质、编码调制与信道容量。',2,320,1,'2026-09-21 08:00:00'),
(7003003,4007,NULL,'第3章 数据链路层与以太网','成帧、差错/流量控制、CSMA/CD 与交换机。',3,320,1,'2026-10-05 08:00:00'),
(7003004,4007,NULL,'第4章 网络层：编址与 ARP','IP 数据报、IPv4 编址、子网划分、ICMP。',4,320,1,'2026-10-19 08:00:00'),
(7003005,4007,NULL,'第5章 路由算法与协议','距离矢量、链路状态、BGP 与 SDN。',5,320,1,'2026-11-02 08:00:00'),
(7003006,4007,NULL,'第6章 传输层','UDP 与 TCP：握手挥手、流量与拥塞控制。',6,320,1,'2026-11-16 08:00:00'),
(7003007,4007,NULL,'第7章 应用层与网络编程','DNS/HTTP/邮件协议与 Socket、Wireshark 实践，兼论无线与移动性。',7,320,1,'2026-11-30 08:00:00'),
(7003008,4007,NULL,'第8章 网络安全与综合实战','密码学、TLS、防火墙 VPN 与组网课程设计。',8,320,1,'2026-12-14 08:00:00');
