INSERT INTO questions (id,type,content,options,correct_answers,difficulty,score,knowledge_points,explanation,usage_count,correct_rate,course_id,created_by,is_active,created_at,updated_at) VALUES
(7006001,'SINGLE_CHOICE','计算机网络中，「协议」的准确含义是？','["通信双方事先约定并共同遵守的通信规则","仅指 TCP/IP 家族中的某一层次标准","硬件接口的电气规范","操作系统提供的 API 集合"]','["A"]','easy',5.0,'["网络体系结构与分层模型"]','协议是三要素：语法、语义、同步/时序。',2,0.63,4007,1004,1,'2026-09-15 10:00:00','2026-10-05 10:00:00'),
(7006002,'SINGLE_CHOICE','OSI 七层模型中，负责端到端可靠传输的是哪一层？','["传输层","网络层","会话层","数据链路层"]','["A"]','easy',5.0,'["OSI 七层模型"]','传输层提供进程间端到端的可靠/不可靠传输。',3,0.39,4007,1004,1,'2026-09-15 10:00:00','2026-10-05 10:00:00'),
(7006003,'SINGLE_CHOICE','TCP/IP 体系中，网络层的协议数据单元称为？','["报文段","帧","数据报/分组","比特"]','["C"]','easy',5.0,'["TCP/IP 四层模型","IP 数据报格式与分片重组"]','IP 层 PDU 为数据报；传输层为报文段。',4,0.61,4007,1004,1,'2026-09-15 10:00:00','2026-10-05 10:00:00'),
(7006004,'SINGLE_CHOICE','若链路带宽 1 Gbps，传输 5 MB 文件的理论最短耗时约为？','["0.04 秒","40 秒","5 秒","0.4 秒"]','["A"]','medium',5.0,'["带宽、时延与吞吐量"]','5MB=40Mbit，40Mbit/1Gbps=0.04s（忽略时延）。',0,0.37,4007,1004,1,'2026-09-15 10:00:00','2026-10-05 10:00:00'),
(7006005,'SINGLE_CHOICE','奈奎斯特定理指出，无噪声理想低通信道（带宽 W）的最高码元传输速率为？','["W","2W","4W","W/2"]','["B"]','medium',5.0,'["奈奎斯特与香农公式"]','最高码元速率 = 2W Baud。',2,0.62,4007,1004,1,'2026-09-15 10:00:00','2026-10-05 10:00:00'),
(7006006,'SINGLE_CHOICE','香农公式给出的信道极限是？','["码元速率上限","数据传输速率上限","帧长上限","带宽产品上限"]','["B"]','medium',5.0,'["奈奎斯特与香农公式"]','C = W·log2(1+S/N) 限定信息传输速率极限。',5,0.83,4007,1004,1,'2026-09-15 10:00:00','2026-10-05 10:00:00'),
(7006007,'SINGLE_CHOICE','以太网中，地址 00-1A-2B-3C-4D-5E 属于？','["IP 地址","MAC 地址","端口号","域名"]','["B"]','easy',5.0,'["MAC 地址与以太网帧格式"]','48 位十六进制是 MAC 地址特征。',5,0.55,4007,1004,1,'2026-09-15 10:00:00','2026-10-05 10:00:00'),
(7006008,'SINGLE_CHOICE','CSMA/CD 的核心思想是？','["先听后发、边发边听、冲突停发、随机重发","时隙轮询避免冲突","令牌传递独占信道","频分复用并行传输"]','["A"]','medium',5.0,'["CSMA/CD 与交换机"]','CSMA/CD 四句口诀。',5,0.81,4007,1004,1,'2026-09-22 10:00:00','2026-10-05 10:00:00'),
(7006009,'SINGLE_CHOICE','CRC 校验能够检测出的错误类型主要是？','["所有错误","绝大多数突发错误","仅单个比特错误","仅介质损坏"]','["B"]','medium',5.0,'["差错检测与 CRC 校验"]','CRC 对突发错误检测能力强，但非完备纠错。',1,0.83,4007,1004,1,'2026-09-22 10:00:00','2026-10-05 10:00:00'),
(7006010,'SINGLE_CHOICE','ARQ 协议中，GBN（回到 N）的特点是？','["只有确认帧需要重传","接收方按序缓存乱序帧","出错帧及其后所有已发帧都要重传","使用选择确认"]','["C"]','medium',5.0,'["滑动窗口与 GBN/SR 协议"]','GBN 累积确认+回退重传；SR 才做选择重传。',1,0.52,4007,1004,1,'2026-09-22 10:00:00','2026-10-05 10:00:00'),
(7006011,'SINGLE_CHOICE','二层交换机工作在 OSI 的哪一层？','["物理层","数据链路层","网络层","传输层"]','["B"]','easy',5.0,'["交换原理与生成树协议","分层模型与封装"]','二层交换机基于 MAC 表转发。',2,0.48,4007,1004,1,'2026-09-22 10:00:00','2026-10-05 10:00:00'),
(7006012,'SINGLE_CHOICE','生成树协议（STP）解决的本质问题是？','["广播风暴与以太网环","IP 地址冲突","TCP 拥塞","DNS 解析缓慢"]','["A"]','medium',5.0,'["交换原理与生成树协议"]','STP 通过阻塞冗余端口消除交换环。',2,0.48,4007,1004,1,'2026-09-22 10:00:00','2026-10-05 10:00:00'),
(7006013,'SINGLE_CHOICE','ARP 协议的作用是？','["把域名解析为 IP","把 IP 地址解析为 MAC 地址","把 MAC 解析为 IP","分配动态 IP"]','["B"]','easy',5.0,'["ARP 协议"]','ARP 解决同网段内三层地址到二层地址的映射。',0,0.76,4007,1004,1,'2026-09-22 10:00:00','2026-10-05 10:00:00'),
(7006014,'SINGLE_CHOICE','IPv4 数据报中的 TTL 字段含义是？','["报文生存时间（最大跳数）","传输时延","窗口大小","校验超时"]','["A"]','medium',5.0,'["IP 数据报格式与分片重组"]','TTL 每经过一个路由器减 1，防止环路。',6,0.39,4007,1004,1,'2026-09-22 10:00:00','2026-10-05 10:00:00'),
(7006015,'SINGLE_CHOICE','子网 192.168.10.0/26 可容纳的可用主机数是？','["62","64","126","30"]','["A"]','hard',5.0,'["IPv4 地址与子网划分","子网划分综合练习"]','2^6-2=62，网络地址与广播地址不可用。',2,0.49,4007,1004,1,'2026-09-22 10:00:00','2026-10-05 10:00:00'),
(7006016,'SINGLE_CHOICE','CIDR 表示法 10.3.0.0/16 聚合了哪段地址？','["10.3.0.0~10.3.255.255","10.0.0.0~10.255.255.255","10.3.0.0~10.3.128.255","172.16.0.0~172.31.255.255"]','["A"]','medium',5.0,'["CIDR 与路由聚合"]','/16 覆盖 256 个 /24。',4,0.73,4007,1004,1,'2026-09-29 10:00:00','2026-10-05 10:00:00'),
